const SIZES = {
  sm: 6,
  md: 10,
  lg: 16
};
function BeadDivider({
  size = 'md',
  width = '100%',
  align = 'stretch',
  style
}) {
  const b = SIZES[size] || 10;
  const bead = (c, x) => 'radial-gradient(circle at ' + x * b + 'px 50%, ' + c + ' 0 ' + b * 0.46 + 'px, transparent ' + b * 0.5 + 'px) 0 0/' + b * 3 + 'px 100% repeat-x';
  const shine = 'radial-gradient(circle at ' + b * 0.4 + 'px 40%, rgba(255,255,255,.55) 0 ' + b * 0.12 + 'px, transparent ' + b * 0.2 + 'px) 0 0/' + b + 'px 100% repeat-x';
  return React.createElement('div', {
    role: 'separator',
    'aria-hidden': true,
    style: {
      height: b,
      width,
      alignSelf: align,
      background: [shine, bead('var(--purple-500)', 0.5), bead('var(--green-500)', 1.5), bead('var(--gold-400)', 2.5)].join(','),
      ...style
    }
  });
}
Object.assign(__ds_scope, { BeadDivider });
